const searchResult = $input.first().json;
const idList = searchResult.esearchresult?.idlist || [];
if (idList.length === 0) {
  return [{ json: { error: 'No articles found', pmids: '' } }];
}
return [{ json: { pmids: idList.join(','), count: idList.length } }];

const rawText = $input.first().json.data || $input.first().json.body || '';

// Parse PubMed XML
const articles = [];
const articleRegex = /<PubmedArticle>[\s\S]*?<\/PubmedArticle>/g;
let match;
while ((match = articleRegex.exec(rawText)) !== null) {
  const xml = match[0];
  const getTag = (tag) => { const m = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\/' + tag + '>')); return m ? m[1].trim() : ''; };
  const title = getTag('ArticleTitle');
  const abs = getTag('AbstractText');
  const journal = getTag('Title');
  const pmid = getTag('PMID');
  const year = getTag('Year');
  const month = getTag('Month');
  const day = getTag('Day');
  const authorNodes = xml.match(/<Author [\s\S]*?<\/Author>/g) || [];
  const authors = authorNodes.slice(0, 3).map(a => {
    const ln = a.match(/<LastName>([^<]*)<\/LastName>/);
    const fn = a.match(/<ForeName>([^<]*)<\/ForeName>/);
    return (ln ? ln[1] : '') + ' ' + (fn ? fn[1][0] : '');
  }).join(', ') + (authorNodes.length > 3 ? ' et al.' : '');
  const pubDate = [year, month, day].filter(Boolean).join(' ');
  articles.push({ title, authors, journal, pubDate, pmid, abstract: abs });
}

// Build prompt asking Claude to generate HTML directly
let prompt = 'You are an expert ophthalmologist. For each article below, write a concise clinical summary in English (2-3 sentences) based on the abstract.\n';
prompt += 'Reply ONLY with a valid JSON array, no markdown, no backticks, no additional text.\n';
prompt += 'Format: [{"pmid":"...", "summary":"..."}]\n\n';

for (const a of articles) {
  prompt += 'PMID: ' + a.pmid + '\n';
  prompt += 'Titolo: ' + a.title + '\n';
  prompt += 'Abstract: ' + (a.abstract || 'Non disponibile') + '\n\n';
}

return [{ json: { articles, totalFound: articles.length, prompt } }];

const claudeRaw = $input.first().json;
const parseData = $('Parse Articles').first().json;
const articles = parseData.articles || [];

let ct = '';
try { ct = claudeRaw.content[0].text; } catch(e) {}
if (!ct) try { ct = claudeRaw.data.content[0].text; } catch(e) {}
if (!ct) ct = JSON.stringify(claudeRaw);

let sMap = {};
const i1 = ct.indexOf(String.fromCharCode(91));
const i2 = ct.lastIndexOf(String.fromCharCode(93));
if (i1 >= 0 && i2 > i1) {
  const jsonStr = ct.substring(i1, i2 + 1);
  try {
    const arr = JSON.parse(jsonStr);
    for (const s of arr) {
      if (s.pmid && s.summary) sMap[String(s.pmid)] = s.summary;
    }
  } catch(e) {}
}

const now = new Date();
const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const my = monthNames[now.getMonth()] + ' ' + now.getFullYear();
const sc = Object.keys(sMap).length;

let h = '<div style="font-family:Georgia,serif;max-width:700px;margin:0 auto;padding:20px">';
h += '<h1 style="color:#2c5282">PubMed Monthly Digest</h1>';
h += '<hr style="border:3px solid #2c5282;margin-bottom:20px">';
h += '<p style="color:#555;font-size:16px">Uveitis & Scleritis \u2014 ' + my + '</p>';
h += '<p style="color:#555">Found <strong>' + articles.length + '</strong> articles \u2014 <strong>' + sc + '</strong> summaries</p>';

for (let i = 0; i < articles.length; i++) {
  const a = articles[i];
  const sm = sMap[String(a.pmid)] || '<em>Summary not available</em>';
  h += '<div style="border-left:4px solid #2c5282;padding:15px 20px;margin:25px 0;background:#f7fafc">';
  h += '<h3 style="margin:0 0 8px">' + (i+1) + '. ' + (a.title||'') + '</h3>';
  h += '<p style="color:#2c5282;margin:0 0 5px"><strong>' + (a.journal||'') + '</strong> | ' + (a.pubDate||'') + '</p>';
  if (a.authors) h += '<p style="color:#888;font-size:13px;margin:0 0 10px">' + a.authors + '</p>';
  h += '<div style="background:#edf2f7;padding:12px;border-radius:6px;margin:10px 0">' + sm + '</div>';
  h += '<a href="https://pubmed.ncbi.nlm.nih.gov/' + a.pmid + '/" style="color:#2c5282">Read on PubMed \u2192</a>';
  h += '</div>';
}
h += '</div>';
return [{ json: { emailSubject: 'PubMed Digest \u2014 Uveitis & Scleritis \u2014 ' + my, emailBody: h } }];
